export function inicializarMenu(){const e=document.querySelector(".menu-hamburguer"),t=document.querySelector(".nav-links");e&&t&&e.addEventListener("click",function(){const n=t.classList.toggle("ativo");e.setAttribute("aria-expanded",String(n))})}export function fecharMenu(){const e=document.querySelector(".menu-hamburguer"),t=document.querySelector(".nav-links");e&&t&&(t.classList.remove("ativo"),e.setAttribute("aria-expanded","false"))}